    void OnChatSay(TContext context, in ChatSay message);

    void OnPing(TContext context, in Ping message);

    void OnSetTarget(TContext context, in SetTarget message);

    void OnSetAttack(TContext context, in SetAttack message);

    void OnSnapshotAck(TContext context, in SnapshotAck message);

    void OnTrainSkill(TContext context, in TrainSkill message);

    void OnEquipItem(TContext context, in EquipItem message);

    void OnUnequipItem(TContext context, in UnequipItem message);

    void OnDiscardItem(TContext context, in DiscardItem message);

    void OnUploadProtocol(TContext context, in UploadProtocol message);

    void OnCastProtocol(TContext context, in CastProtocol message);

    void OnCancelProtocol(TContext context, in CancelProtocol message);
}

