/// <summary>
/// Decodes one packet and calls the matching handler method. Throws <see cref="WireFormatException"/>
/// for unknown ids, ids from the wrong direction, malformed bodies and trailing bytes.
/// </summary>
public static class WireDispatch
{
    /// <returns>The id of the dispatched message.</returns>
    public static ushort DispatchServerBound<TContext>(System.ReadOnlySpan<byte> packet, IServerBoundHandler<TContext> handler, TContext context)
    {
        System.ArgumentNullException.ThrowIfNull(handler);
        var reader = new WireReader(packet);
        var id = reader.ReadU16();
        switch (id)
        {
            case MoveIntent.Id:
            {
                var message = MoveIntent.Read(ref reader);
                reader.EnsureEnd();
                handler.OnMoveIntent(context, message);
                return id;
            }
            case ChatSay.Id:
            {
                var message = ChatSay.Read(ref reader);
                reader.EnsureEnd();
                handler.OnChatSay(context, message);
                return id;
            }
            case Ping.Id:
            {
                var message = Ping.Read(ref reader);
                reader.EnsureEnd();
                handler.OnPing(context, message);
                return id;
            }
            case SetTarget.Id:
            {
                var message = SetTarget.Read(ref reader);
                reader.EnsureEnd();
                handler.OnSetTarget(context, message);
                return id;
            }
            case SetAttack.Id:
            {
                var message = SetAttack.Read(ref reader);
                reader.EnsureEnd();
                handler.OnSetAttack(context, message);
                return id;
            }
            case SnapshotAck.Id:
            {
                var message = SnapshotAck.Read(ref reader);
                reader.EnsureEnd();
                handler.OnSnapshotAck(context, message);
                return id;
            }
            case TrainSkill.Id:
            {
                var message = TrainSkill.Read(ref reader);
                reader.EnsureEnd();
                handler.OnTrainSkill(context, message);
                return id;
            }
            case EquipItem.Id:
            {
                var message = EquipItem.Read(ref reader);
                reader.EnsureEnd();
                handler.OnEquipItem(context, message);
                return id;
            }
            case UnequipItem.Id:
            {
                var message = UnequipItem.Read(ref reader);
                reader.EnsureEnd();
                handler.OnUnequipItem(context, message);
                return id;
            }
            case DiscardItem.Id:
            {
                var message = DiscardItem.Read(ref reader);
                reader.EnsureEnd();
                handler.OnDiscardItem(context, message);
                return id;
            }
            case UploadProtocol.Id:
            {
                var message = UploadProtocol.Read(ref reader);
                reader.EnsureEnd();
                handler.OnUploadProtocol(context, message);
                return id;
            }
            case CastProtocol.Id:
            {
                var message = CastProtocol.Read(ref reader);
                reader.EnsureEnd();
                handler.OnCastProtocol(context, message);
                return id;
            }
            case CancelProtocol.Id:
            {
                var message = CancelProtocol.Read(ref reader);
                reader.EnsureEnd();
                handler.OnCancelProtocol(context, message);
                return id;
            }
            default:
                throw new WireFormatException($"Message id {id} is not a ServerBound message.");
        }
    }

