        var reader = new WireReader(packet);
        var id = reader.ReadU16();
        switch (id)
        {
            case Welcome.Id:
            {
                var message = Welcome.Read(ref reader);
                reader.EnsureEnd();
                handler.OnWelcome(context, message);
                return id;
            }
            case ChatMessage.Id:
            {
                var message = ChatMessage.Read(ref reader);
                reader.EnsureEnd();
                handler.OnChatMessage(context, message);
                return id;
            }
            case Pong.Id:
            {
                var message = Pong.Read(ref reader);
                reader.EnsureEnd();
                handler.OnPong(context, message);
                return id;
            }
            case Disconnecting.Id:
            {
