                return id;
            }
            case EntityInfo.Id:
            {
                var message = EntityInfo.Read(ref reader);
                reader.EnsureEnd();
                handler.OnEntityInfo(context, message);
                return id;
            }
            case CombatEvent.Id:
            {
                var message = CombatEvent.Read(ref reader);
                reader.EnsureEnd();
                handler.OnCombatEvent(context, message);
                return id;
            }
            case EntityDied.Id:
            {
                var message = EntityDied.Read(ref reader);
                reader.EnsureEnd();
                handler.OnEntityDied(context, message);
                return id;
            }
            case SelfStatus.Id:
            {
                var message = SelfStatus.Read(ref reader);
                reader.EnsureEnd();
                handler.OnSelfStatus(context, message);
                return id;
            }
            case Respawned.Id:
            {
                var message = Respawned.Read(ref reader);
                reader.EnsureEnd();
                handler.OnRespawned(context, message);
                return id;
            }
            case DeltaSnapshot.Id:
            {
                var message = DeltaSnapshot.Read(ref reader);
                reader.EnsureEnd();
                handler.OnDeltaSnapshot(context, message);
                return id;
            }
            case CharacterSheet.Id:
            {
                var message = CharacterSheet.Read(ref reader);
                reader.EnsureEnd();
                handler.OnCharacterSheet(context, message);
                return id;
            }
            case InventoryState.Id:
            {
                var message = InventoryState.Read(ref reader);
                reader.EnsureEnd();
                handler.OnInventoryState(context, message);
                return id;
            }
            case ProtocolState.Id:
            {
                var message = ProtocolState.Read(ref reader);
                reader.EnsureEnd();
                handler.OnProtocolState(context, message);
                return id;
            }
            case XpGained.Id:
            {
                var message = XpGained.Read(ref reader);
                reader.EnsureEnd();
                handler.OnXpGained(context, message);
                return id;
            }
            case Notice.Id:
            {
                var message = Notice.Read(ref reader);
                reader.EnsureEnd();
                handler.OnNotice(context, message);
                return id;
